import type { Page, Response } from 'playwright-core';

/** Explicit synthetic-target UI contract, not a generic SSO detector.
 * Cookies and a 200 login page cannot prove authentication. Unknown UI fails closed. */
export async function hasAuthenticatedAccount(page: Page, response: Response): Promise<boolean> {
  if (response.status() < 200 || response.status() >= 300) return false;
  if (await page.locator('input[type="password"]').count() !== 0) return false;
  const account = page.getByRole('status', { name: 'Current signed-in account', exact: true });
  if (await account.count() !== 1 || !await account.isVisible()) return false;
  return /^Signed in as\s+\S/u.test((await account.innerText()).trim());
}

import { describe, expect, it } from 'vitest';
import type { Page, Response } from 'playwright-core';
import { hasAuthenticatedAccount } from './authentication-proof.js';

function fixture(options: { status?: number; password?: boolean; count?: number; visible?: boolean; text?: string } = {}) {
  const page = {
    locator: () => ({ count: async () => options.password ? 1 : 0 }),
    getByRole: (role: string, query: { name: string; exact: boolean }) => {
      expect(role).toBe('status');
      expect(query).toEqual({ name: 'Current signed-in account', exact: true });
      return { count: async () => options.count ?? 1, isVisible: async () => options.visible ?? true, innerText: async () => options.text ?? 'Signed in as audit.readonly' };
    },
  } as unknown as Page;
  const response = { status: () => options.status ?? 200 } as Response;
  return hasAuthenticatedAccount(page, response);
}

describe('positive authenticated UI proof', () => {
  it('accepts the declared visible authenticated account', async () => { expect(await fixture()).toBe(true); });
  it.each([199, 300, 401, 403, 500])('refuses status %s', async status => { expect(await fixture({ status })).toBe(false); });
  it('refuses a password form even beside a claimed account', async () => { expect(await fixture({ password: true })).toBe(false); });
  it.each([0, 2])('refuses %s account markers', async count => { expect(await fixture({ count })).toBe(false); });
  it('refuses hidden state', async () => { expect(await fixture({ visible: false })).toBe(false); });
  it('requires an identity', async () => { expect(await fixture({ text: 'Signed in as   ' })).toBe(false); });
  it('does not inspect a cookie jar to decide authentication', async () => { expect(await fixture({ text: 'Not signed in.' })).toBe(false); });
});

import { createServer } from 'node:http';
import { once } from 'node:events';
import { describe, expect, it } from 'vitest';
import { PlaywrightBrowserExecution } from '@intellifin/infrastructure/browser';
import { ManifestCredentialResolver } from '@intellifin/infrastructure/credentials';

const token = 'synthetic-authentication-regression';
const credentialRef = 'cred://synthetic/authentication-regression';
const marker = '<p role="status" aria-label="Current signed-in account">Signed in as audit.readonly</p>';

describe('actual browser authentication confirmation', () => {
  it.each(['unrelated', 'stale', 'rejected-session'] as const)('does not trust a %s cookie on a successful login page', async mode => {
    let submissions = 0;
    const server = createServer((request, response) => {
      const chunks: Buffer[] = [];
      request.on('data', (chunk: Buffer) => chunks.push(chunk));
      request.on('end', () => {
        if (request.method === 'POST' && request.url === '/target/sign-in') {
          submissions += 1;
          expect(new URLSearchParams(Buffer.concat(chunks).toString()).get('credential')).toBe(token);
          response.writeHead(303, { location: '/target', 'set-cookie': 'session=granted; Path=/' });
          response.end();
          return;
        }
        const signedIn = mode !== 'rejected-session' && String(request.headers.cookie).includes('session=granted');
        response.writeHead(200, { 'content-type': 'text/html' });
        response.end('<!doctype html><body>' + (signedIn ? marker : '<form method="post" action="/target/sign-in"><input type="password" name="credential"><button type="submit">Sign in</button></form>') + '</body>');
      });
    });
    server.listen(0, '127.0.0.1');
    await once(server, 'listening');
    const origin = `http://127.0.0.1:${(server.address() as { port: number }).port}/target`;
    const browser = new PlaywrightBrowserExecution({ mode: 'local' });
    try {
      const workspace = await browser.create({ runId: 'authentication-test', policy: { allowedOrigins: [origin] }, timeoutMs: 10000 });
      await workspace.context.addCookies([{ name: mode === 'unrelated' ? 'preferences' : 'session', value: 'stale', url: origin }]);
      const credential = await new ManifestCredentialResolver(new Map([[credentialRef, token]])).resolve(credentialRef, 1000);
      const action = { action: 'navigate' as const, destination: origin, parameters: {}, credential };
      const result = await browser.perform(workspace.ref, action, 10000);
      expect(submissions).toBe(1);
      expect(result.session).toBe(mode !== 'rejected-session');
      if (mode !== 'rejected-session') {
        expect((await browser.perform(workspace.ref, action, 10000)).session).toBe(true);
        expect(submissions).toBe(1);
      }
    } finally {
      await browser.close();
      server.closeAllConnections();
      await new Promise<void>(resolve => server.close(() => resolve()));
    }
  });
});
